class A:
 x=1
 def __getattribute__(self,name):
  print("read",name)
  return 7
print(A().x)

class A:
 def __init__(self): self.x=[7]
 def __getattribute__(self,name): return object.__getattribute__(self,name)
print(A().x[0])

class A:
 x=7
 def __getattribute__(self,name):
  print("base",name)
  return super().__getattribute__(name)
class B(A): pass
print(B().x)

class A:
 def __getattribute__(self,name):
  print("first",name)
  raise AttributeError("missing")
 def __getattr__(self,name):
  print("second",name)
  return 9
print(A().x)

class A:
 def __getattribute__(self,name): raise TypeError("body")
 def __getattr__(self,name): print("never")
A().x

class A:
 def __getattribute__(self,name): raise StopIteration("body")
 def __getattr__(self,name): print("never")
A().x

class A:
 def __getattribute__(self,name): raise ValueError("body")
 def __getattr__(self,name): print("never")
A().x

class A:
 def __getattr__(self,name):
  print("once")
  raise AttributeError("still missing")
A().x

class A:
 @property
 def x(self):
  print("property")
  raise AttributeError("missing")
 def __getattr__(self,name): return 7
print(A().x)

class D:
 def __get__(self,obj,owner): return 7
 def __set__(self,obj,value): pass
class A:
 x=D()
 def __getattribute__(self,name): return object.__getattribute__(self,name)
a=A()
a.x=9
print(a.x)

class D:
 def __get__(self,obj,owner):
  print(obj is None,owner.__name__)
  def read(name): return [name]
  return read
class A: __getattribute__=D()
print(A().x[0])

class D:
 def __get__(self,obj,owner): raise AttributeError("binding")
class A:
 __getattribute__=D()
 def __getattr__(self,name): return 7
print(A().x)

class D:
 def __get__(self,obj,owner):
  def missing(name): return name
  return missing
class A: __getattr__=D()
print(A().x)

class A:
 @staticmethod
 def __getattribute__(name):
  return name
print(A().x)

class A:
 @classmethod
 def __getattribute__(cls,name):
  return cls.__name__
print(A().x)

class A:
 def __getattribute__(self,name): raise ValueError("never")
 def __len__(self): return 3
 def __add__(self,other): return 7
a=A()
print(len(a),bool(a),a+1,type(a) is A,isinstance(a,A))

class A:
 def __getattr__(self,name): return 7
object.__getattribute__(A(),"x")

class A:
 def __getattr__(self,name): raise AttributeError("missing")
a=A()
print(getattr(a,"x",[7])[0],hasattr(a,"x"))

class A:
 def __getattribute__(self,name): print("never")
getattr(A(),7)

class A:
 def __getattribute__(self,name): print("never")
object.__getattribute__(A(),7)

class A:
 def __getattribute__(self,name): print("never")
object.__getattribute__(A())

class A:
 def __getattribute__(self,name): print("never")
object.__getattribute__(A(),"x",1)

class A:
 def __getattribute__(self,name): print("never")
object.__getattribute__(A(),name="x")

class A:
 def __getattribute__(self,name): yield name
print(next(A().x))

class A:
 def __setattr__(self,name,value):
  print(name,value)
  return 9
a=A()
print(setattr(a,"x",7))

class A:
 def __setattr__(self,name,value): object.__setattr__(self,name,value+1)
a=A()
a.x=6
print(a.x)

class A:
 def __delattr__(self,name):
  print("delete",name)
  return 9
a=A()
print(delattr(a,"missing"))

class A:
 def __delattr__(self,name): object.__delattr__(self,name)
a=A()
a.x=7
del a.x
print(hasattr(a,"x"))

class A:
 def __setattr__(self,name,value): super().__setattr__(name,value)
 def __delattr__(self,name): super().__delattr__(name)
class B(A): pass
b=B()
b.x=7
print(b.x)
del b.x
print(hasattr(b,"x"))

class A:
 @property
 def x(self): return self.saved
 @x.setter
 def x(self,value):
  print("property",value)
  object.__setattr__(self,"saved",value)
 def __setattr__(self,name,value):
  print("hook",name)
  object.__setattr__(self,name,value)
a=A()
a.x=7
print(a.x)

class D:
 def __get__(self,obj,owner):
  def write(name,value): object.__setattr__(obj,name,value)
  return write
class A: __setattr__=D()
a=A()
a.x=7
print(a.x)

class D:
 def __get__(self,obj,owner):
  def remove(name): object.__delattr__(obj,name)
  return remove
class A: __delattr__=D()
a=A()
a.x=7
del a.x
print(hasattr(a,"x"))

class A:
 @property
 def x(self): return 1
 def __setattr__(self,name,value): print(name,value)
a=A()
a.x=7
print(a.x)

class A:
 def __getattribute__(self,name):
  print("get",name)
  return 2
 def __setattr__(self,name,value): print("set",name,value)
a=A()
a.x+=3

class A:
 def __setattr__(self,*args): raise AttributeError("body")
 def __getattr__(self,name): print("never")
a=A()
a.x=7

class A:
 def __delattr__(self,*args): raise AttributeError("body")
 def __getattr__(self,name): print("never")
a=A()
del a.x

class A:
 def __setattr__(self,name,value): print("never")
 def __delattr__(self,name): print("never")
A.x=7
print(A.x)
del A.x

class B: pass
class A:
 @property
 def __class__(self):
  print("advertised")
  return B
a=A()
print(a.__class__ is B,type(a) is A,isinstance(a,A),isinstance(a,B))

class B: pass
class A:
 def __getattribute__(self,name):
  if name=="__class__": return B
  return object.__getattribute__(self,name)
a=A()
print(a.__class__ is B,isinstance(a,B),type(a) is A)

class B: pass
class A:
 @property
 def __class__(self): raise AttributeError("body")
print(isinstance(A(),B))

class B: pass
class A:
 @property
 def __class__(self): raise TypeError("body")
print(isinstance(A(),B))

class B: pass
class A:
 @property
 def __class__(self): raise StopIteration("body")
print(isinstance(A(),B))

class B: pass
class A:
 @property
 def __class__(self):
  print("check")
  return B
a=A()
print(isinstance(a,(A,7)),isinstance(a,(B,A)))

class A:
 def __getattribute__(self,name): print("never")
print(isinstance(A(),(7,A)))

class Base:
 def f(self): return 7
class B(Base): pass
class A:
 @property
 def __class__(self):
  print("check")
  return B
a=A()
s=super(B,a)
print(s.f(),s.__self__ is a,s.__self_class__ is B)

class A:
 @property
 def __class__(self): raise ValueError("never")
class B(A): pass
b=B()
s=super(A,b)
print(s.__self_class__ is B,type(b) is B,isinstance(b,A))

class B: pass
class A:
 @property
 def __class__(self): raise AttributeError("body")
super(B,A())

class B: pass
class A:
 @property
 def __class__(self): raise ValueError("body")
super(B,A())

class A:
 def __dir__(self): return ["x"]
print(dir(A())[0])

class M(type):
 @classmethod
 def __prepare__(cls,name,bases): return {}
class A(metaclass=M): pass
print(A.__name__)

class A:
 def __init_subclass__(cls): print(cls.__name__)
class B(A): pass

class A:
 def __getattribute__(self,name):
  A.__getattr__=lambda self,name: 9
  raise AttributeError("missing")
 def __getattr__(self,name): return 7
print(A().x)

